import{_ as e,o as a,c as o,a6 as s}from"./chunks/framework.O8w_gp-L.js";const c=JSON.parse('{"title":"Stuck? Try this","description":"","frontmatter":{},"headers":[],"relativePath":"guides/stuck.md","filePath":"guides/stuck.md"}'),n={name:"guides/stuck.md"};function r(i,t,l,h,d,g){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="stuck-try-this" tabindex="-1">Stuck? Try this <a class="header-anchor" href="#stuck-try-this" aria-label="Permalink to &quot;Stuck? Try this&quot;">​</a></h1><h2 id="i-don-t-know-where-to-go" tabindex="-1">I don&#39;t know where to go. <a class="header-anchor" href="#i-don-t-know-where-to-go" aria-label="Permalink to &quot;I don&#39;t know where to go.&quot;">​</a></h2><p>Walk to the <strong>Stage Gate</strong> in Loomhaven and press <strong>Z</strong> (<strong>G</strong> with WASD keys). The chapter map shows your next stage and the level it suits.</p><h2 id="a-stage-is-too-hard" tabindex="-1">A stage is too hard. <a class="header-anchor" href="#a-stage-is-too-hard" aria-label="Permalink to &quot;A stage is too hard.&quot;">​</a></h2><ul><li><strong>Forge a better weapon.</strong> The Forge opens after 1-1. If the chapter card says &quot;Your weapon could be stronger&quot;, it&#39;s time.</li><li><strong>Replay cleared stages</strong> for XP and materials, then come back stronger.</li><li><strong>Spend your skill points.</strong> Auto skill points is on unless you turned it off. Check <strong>Character → Skills</strong>.</li><li><strong>Learn the moves.</strong> Open <strong>Pause → Combo list</strong> in any stage.</li><li><strong>Practice at the Drill post</strong> (opens after 1-2). It has short drills and <strong>Boss practice</strong>. Nothing to lose.</li><li><strong>Bring a friend.</strong> See <em>Playing together</em> in &lt;#GUIDES&gt;.</li><li><strong>Use your items.</strong> Keys <strong>1-4</strong> use items such as Field Dressings. You can use 3 per stage.</li></ul><h2 id="_5-5-won-t-start" tabindex="-1">5-5 won&#39;t start. <a class="header-anchor" href="#_5-5-won-t-start" aria-label="Permalink to &quot;5-5 won&#39;t start.&quot;">​</a></h2><p>Summit of the Bell needs your <strong>second vow</strong>. At <strong>Lv 30</strong>, go to your own shrine in the <strong>Hall of Memories</strong> and press <strong>Z</strong>. You can also clear <strong>5-4</strong> and take the trial from its results (that needs Lv 30 too). In a party, everyone needs the vow.</p><h2 id="a-stand-in-loomhaven-is-closed" tabindex="-1">A stand in Loomhaven is closed. <a class="header-anchor" href="#a-stand-in-loomhaven-is-closed" aria-label="Permalink to &quot;A stand in Loomhaven is closed.&quot;">​</a></h2><p>It opens after a certain stage: the tag says which one, like &quot;Opens after Stage 1-4&quot;. If it says <strong>Opens in a later update</strong>, it isn&#39;t ready yet.</p><h2 id="my-reward-says-will-be-paid-on-your-next-visit" tabindex="-1">My reward says &quot;Will be paid on your next visit.&quot; <a class="header-anchor" href="#my-reward-says-will-be-paid-on-your-next-visit" aria-label="Permalink to &quot;My reward says &quot;Will be paid on your next visit.&quot;&quot;">​</a></h2><p>It&#39;s saved. It arrives next time you&#39;re in Loomhaven.</p><h2 id="my-friend-and-i-can-t-start-the-same-stage" tabindex="-1">My friend and I can&#39;t start the same stage. <a class="header-anchor" href="#my-friend-and-i-can-t-start-the-same-stage" aria-label="Permalink to &quot;My friend and I can&#39;t start the same stage.&quot;">​</a></h2><p>You both need to have reached it. Pick one you&#39;ve both opened.</p><p><strong>Found a bug?</strong> Post it in &lt;#BUG_REPORTS&gt;: what happened, what you expected, your device and the stage. Check the pinned known issues first. <strong>Found an exploit?</strong> Tell us privately with a ticket in &lt;#TICKETS&gt;. <strong>Lost progress?</strong> Rejoin first, then open a ticket.</p>',14)])])}const p=e(n,[["render",r]]);export{c as __pageData,p as default};
